//! Cross-check against CORA: `tests/cora/generate.m` runs the same operations
//! in CORA and writes their interval hulls to `tests/cora/reference.txt`.

use std::collections::HashMap;

use nalgebra::DMatrix;
use polyzonotope::{FactorId, IntervalBox, Reduction, SparsePolyZonotope};

/// The reference file, regenerated by `tests/cora/generate.m`.
const REFERENCE: &str = include_str!("../cora/reference.txt");

/// One case: its matrices by name, each stored column-major.
type Case = HashMap<String, DMatrix<f64>>;

/// Every case in the reference file.
fn cases() -> Vec<Case> {
    let mut cases = Vec::new();
    for line in REFERENCE.lines().filter(|l| !l.starts_with('#')) {
        let mut words = line.split_whitespace();
        let name = words.next().expect("every line starts with a name");
        if name == "case" {
            cases.push(Case::new());
            continue;
        }

        let mut number = || {
            words
                .next()
                .expect("a value")
                .parse::<f64>()
                .expect("a number")
        };
        let (rows, cols) = (as_count(number()), as_count(number()));
        let values: Vec<f64> = (0..rows * cols).map(|_| number()).collect();
        let case = cases.last_mut().expect("a case header comes first");
        case.insert(
            name.to_owned(),
            DMatrix::from_column_slice(rows, cols, &values),
        );
    }

    // An empty or truncated reference would make every check pass vacuously.
    assert_eq!(
        cases.len(),
        8,
        "tests/cora/reference.txt should hold eight cases"
    );
    cases
}

/// A non-negative whole number read as `f64`, as a count.
#[expect(
    clippy::cast_possible_truncation,
    clippy::cast_sign_loss,
    reason = "matrix sizes in the reference file are small whole numbers"
)]
fn as_count(x: f64) -> usize {
    x as usize
}

/// The case's set, with or without its independent generators.
fn set(case: &Case, independent: bool) -> SparsePolyZonotope {
    let n = case["c"].nrows();
    let gi = if independent {
        case["GI"].clone()
    } else {
        DMatrix::zeros(n, 0)
    };
    #[expect(
        clippy::cast_possible_truncation,
        clippy::cast_sign_loss,
        reason = "exponents in the reference file are small whole numbers"
    )]
    let e = case["E"].map(|x| x as u32);
    let ids = FactorId::fresh_n(e.nrows());

    // CORA's constructor merges equal exponent columns; compact() does the same.
    SparsePolyZonotope::new(
        case["c"].column(0).into_owned(),
        case["G"].clone(),
        gi,
        e,
        ids,
    )
    .expect("the reference describes consistent sets")
    .compact()
}

/// Largest gap between the bounds of `ours` and CORA's `theirs`, relative to the box size.
fn gap(ours: &IntervalBox, theirs: &DMatrix<f64>) -> f64 {
    let scale = 1.0 + theirs.amax();
    ours.0
        .iter()
        .enumerate()
        .map(|(i, iv)| {
            (iv.lo - theirs[(i, 0)])
                .abs()
                .max((iv.hi - theirs[(i, 1)]).abs())
        })
        .fold(0.0, f64::max)
        / scale
}

/// Whether every bound of `ours` is at least as tight as CORA's, up to `slack`.
fn at_least_as_tight(ours: &IntervalBox, theirs: &DMatrix<f64>, slack: f64) -> bool {
    ours.0
        .iter()
        .enumerate()
        .all(|(i, iv)| iv.lo >= theirs[(i, 0)] - slack && iv.hi <= theirs[(i, 1)] + slack)
}

/// The exact operations and enclosures that both libraries define the same
/// way agree with CORA to rounding.
#[test]
fn enclosures_match_cora() {
    for (k, case) in cases().iter().enumerate() {
        let (pz, plain) = (set(case, true), set(case, false));
        let quad = plain.quadratic_map(&[case["Q1"].clone(), case["Q2"].clone()]);
        let plus = pz.exact_plus(&pz.linear_map(&case["M"]));
        let order = case["order"][(0, 0)];
        let checks = [
            ("hull", pz.interval_hull()),
            ("quad", quad.interval_hull()),
            ("plus", plus.interval_hull()),
            (
                "girard",
                pz.to_zonotope()
                    .reduce(order, Reduction::Girard)
                    .interval_hull(),
            ),
            (
                "pca",
                pz.to_zonotope().reduce(1.0, Reduction::Pca).interval_hull(),
            ),
        ];
        for (name, ours) in checks {
            let g = gap(&ours, &case[name]);
            assert!(
                g < 1e-9,
                "case {}: {name} differs from CORA by {g:e}: {ours:?}",
                k + 1
            );
        }
    }
}

/// Girard and PCA reductions keep the same generators as CORA's: the
/// support functions of the reduced zonotopes agree in fixed directions
/// (plain mode), or ours dominate (`sound`).
#[test]
fn reductions_match_cora_in_every_direction() {
    for (k, case) in cases().iter().enumerate() {
        let z = set(case, true).to_zonotope();
        let order = case["order"][(0, 0)];
        let reduced = [
            ("girard_support", z.reduce(order, Reduction::Girard)),
            ("pca_support", z.reduce(1.0, Reduction::Pca)),
        ];
        for (name, r) in reduced {
            for (j, d) in case["D"].column_iter().enumerate() {
                let ours = d.dot(r.center())
                    + r.generators()
                        .column_iter()
                        .map(|g| d.dot(&g).abs())
                        .sum::<f64>();
                let theirs = case[name][(0, j)];
                let tol = 1e-9 * (1.0 + theirs.abs());
                // Under `sound`, error generators can push the count over the order, so
                // more generators get boxed: the result is then a superset of CORA's.
                let agrees = if cfg!(feature = "sound") {
                    ours >= theirs - tol
                } else {
                    (ours - theirs).abs() < tol
                };
                assert!(agrees, "case {}: {name}[{j}]: {ours} vs {theirs}", k + 1);
            }
        }
    }
}

/// Our split hull is never looser than CORA's split-based `interval`.
#[test]
fn split_hull_is_at_least_as_tight_as_cora() {
    for (k, case) in cases().iter().enumerate() {
        let ours = set(case, true).interval_hull_split(1e-6, 200);
        assert!(
            at_least_as_tight(&ours, &case["split"], 1e-9),
            "case {}: {ours:?} vs {}",
            k + 1,
            case["split"]
        );
    }
}
